const defaultItems=['鐵屑','鐵粒','鐵花','製程報廢','調機品','鐵皮/鐵牌/鐵線','廠商下腳料','白鐵','鋁合金','製程下腳料','S10設備製程報廢'];
const itemWords=[['Iron shavings','Virutas de hierro','Phoi sắt'],['Iron granules','Gránulos de hierro','Hạt sắt'],['Metal offcuts','Recortes metálicos','Mảnh sắt'],['Production scrap','Desechos de producción','Phế phẩm sản xuất'],['Setup scrap','Desecho de ajuste','Phế phẩm chỉnh máy'],['Iron sheets / tags / wire','Láminas / placas / alambre de hierro','Tôn / thẻ / dây sắt'],['Vendor scrap','Chatarra de proveedores','Phế liệu nhà cung cấp'],['Stainless steel','Acero inoxidable','Thép không gỉ'],['Aluminum alloy','Aleación de aluminio','Hợp kim nhôm'],['Process scrap','Chatarra del proceso','Phế liệu công đoạn'],['S10 equipment production scrap','Desechos de producción del equipo S10','Phế phẩm sản xuất thiết bị S10']];
const itemLabel=x=>{const i=defaultItems.indexOf(x);return i<0?esc(x):formContentHtml({zh:x,en:itemWords[i][0],es:itemWords[i][1],vi:itemWords[i][2]});};
