function quote(){const rec=state.draft,disabled=write()?'':'disabled',priceDisabled='disabled';return `<p class="notice">${txt('sqReadOnly')}</p><p class="notice">${txt('scNames')}</p><div class="sc-meta">${Object.entries(metaFields).map(([f,k])=>`<label>${txt(k)}${input('detail:'+f,(f==='vendor'?rec.quote_details?.vendor:null)||rec.details[f]||'',`${f==='vendor'?'disabled':disabled} ${f==='application_date'?'type="date"':f.startsWith('actual_')?'type="number" min="0" step="0.0001"':'maxlength="2000"'}`)}</label>`).join('')}</div><div class="sc-scroll"><table class="sc-table"><thead><tr><th>${txt('scItem')}</th><th>${txt('scPrice')} (${esc(rec.details.currency)})</th><th>${txt('scRemove')}</th></tr></thead><tbody>${rec.quotes.map((q,i)=>`<tr><td>${input(`quote:${i}:item`,q.item,`maxlength="100" ${disabled}`)}</td><td>${input(`quote:${i}:price`,q.price??'',`type="number" min="0" max="1000000" step="0.0001" ${priceDisabled}`)}</td><td><button class="btn secondary" data-sc-remove-quote="${i}" ${write()&&!rec.rows.some(r=>r.item===q.item)?'':'disabled'}>${txt('scRemove')}</button></td></tr>`).join('')}</tbody></table></div><div class="filter-row"><button id="scAddItem" class="btn secondary" ${disabled}>${txt('scAddItem')}</button><button id="scSave" class="btn primary" ${disabled}>${txt('scSave')}</button></div>`;}
